using Microsoft.EntityFrameworkCore;using pcms.Application.Inventory;using pcms.Domain.Entities;using pcms.Domain.Enums;using pcms.Infrastructure.Persistence;
namespace pcms.Infrastructure.Services;
public class InventoryLotService(AppDbContext db):IInventoryLotService
{public async Task<IEnumerable<LotDto>> GetAsync(string? search){var q=db.SupplyInventoryLots.AsNoTracking().Include(x=>x.SupplyItem).Where(x=>x.IsActive);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.ScanCode.Contains(search)||x.SupplyItem.Name.Contains(search));var xs=await q.OrderBy(x=>x.SupplyItem.Name).ThenBy(x=>x.ScanCode).ToListAsync();return await Task.WhenAll(xs.Select(Map));}
 public async Task<LotDto?> GetByScanAsync(string code){var x=await db.SupplyInventoryLots.AsNoTracking().Include(x=>x.SupplyItem).FirstOrDefaultAsync(x=>x.ScanCode==code.Trim()&&x.IsActive);return x is null?null:await Map(x);}
 public async Task<LotDto> CreateAsync(LotInput i){if(i.InitialQuantity<=0||string.IsNullOrWhiteSpace(i.ScanCode))throw new ArgumentException("Código y cantidad inicial son obligatorios.");var item=await db.SupplyItems.FirstOrDefaultAsync(x=>x.Id==i.SupplyItemId&&x.IsActive&&x.TrackInventory)??throw new ArgumentException("El insumo no existe o no controla inventario.");if(await db.SupplyInventoryLots.AnyAsync(x=>x.ScanCode==i.ScanCode.Trim()))throw new InvalidOperationException("El código de lote ya existe.");var x=new SupplyInventoryLot{Id=Guid.NewGuid(),SupplyItemId=item.Id,ScanCode=i.ScanCode.Trim(),ManufacturerLotNumber=i.ManufacturerLotNumber,InitialQuantity=decimal.Round(i.InitialQuantity,3),UnitOfMeasure=item.UnitOfMeasure,ReceivedAt=i.ReceivedAt??DateTime.UtcNow,Notes=i.Notes,CreatedAt=DateTime.UtcNow};db.Add(x);await db.SaveChangesAsync();return await Map(x);}
 async Task<LotDto> Map(SupplyInventoryLot x){var ms=await db.SupplyInventoryMovements.Where(m=>m.SupplyInventoryLotId==x.Id).Select(m=>new{m.MovementType,m.Quantity}).ToListAsync();var remaining=x.InitialQuantity+ms.Sum(m=>Sign(m.MovementType)*m.Quantity);return new(x.Id,x.SupplyItemId,x.SupplyItem.Name,x.ScanCode,x.ManufacturerLotNumber,x.InitialQuantity,remaining,x.UnitOfMeasure,x.ReceivedAt,x.IsActive);}static int Sign(SupplyInventoryMovementType t)=>t is SupplyInventoryMovementType.ManualAdjustmentDecrease or SupplyInventoryMovementType.Consumption or SupplyInventoryMovementType.Waste or SupplyInventoryMovementType.PurchaseReturn or SupplyInventoryMovementType.ManufacturingConsumption?-1:1;}
